def cleanup_duplicate_active_enrollments(apps, schema_editor):
    Enrollment = apps.get_model('academics', 'Enrollment')
    # Get all active enrollments, ordered by student and newest first
    active_enrollments = Enrollment.objects.filter(status='active').order_by('-enrolled_at')
    
    seen_students = set()
    for enrollment in active_enrollments:
        if enrollment.student_id in seen_students:
            enrollment.status = 'dropped'
            enrollment.save(update_fields=['status'])
        else:
            seen_students.add(enrollment.student_id)

